// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./CasinoGameBaseV6.sol";

/**
 * @title KenoGameV6 — RABBIT KENO on the V6 base
 * @notice 40 numbers, 10 drawn from a FUTURE block hash at reveal. The player picks 1–10 numbers and a
 *         risk (0 Low · 1 Classic · 2 High) before the entropy block and is paid by how many picks are
 *         among the ten drawn. BIT-FOR-BIT mirror of the app's kenoEngine.ts (drawSeed / PAYS).
 *
 * Draw j = mod(40 − j) into the numbers not yet drawn, in number order. Pay rows are the fair
 * hypergeometric odds (raw EV 0.997…1, never above 1); the room RTP scales every payout.
 * Picks / draw are bitmasks: bit n − 1 = number n.
 *
 * RNG stream (shared with the other V6 engines): draw i = 64-bit chunk (i % 4) of
 * keccak256(seed ‖ uint32(i / 4)), lowest chunk first.
 */
contract KenoGameV6 is CasinoGameBaseV6 {
    uint256 public constant NUMBERS = 40;
    uint256 public constant DRAWN = 10;
    uint256 public constant MAX_PICKS = 10;
    uint256 public constant RISKS = 3;

    /// @dev PAYS[risk][picks − 1][hits] (bp) as 195 big-endian uint32: per risk 65 entries, picks k starts at (k − 1)(k + 2) / 2
    bytes internal constant PAYS = hex"";

    struct Ticket {
        address player; uint48 commitBlock; uint16 rtpBP; uint8 risk; uint8 hits; bool settled;
        uint64 picks; uint64 drawn;
        uint128 amount; uint128 maxPayout;
        uint128 payout;
    }
    mapping(uint256 => Ticket) internal _tickets;
    uint256 public totalTickets;

    event TicketCommitted(uint256 indexed id, address indexed player, uint256 amount, uint8 risk, uint256 picks);
    event TicketSettled(uint256 indexed id, address indexed player, bytes32 seed, uint256 picks, uint256 drawn, uint8 hits, uint256 payout);
    event TicketForfeited(uint256 indexed id, address indexed player);

    constructor(InitArgs memory a) CasinoGameBaseV6(a) {}

    function _betCount() internal view override returns (uint256) { return totalTickets; }

    // ── odds ─────────────────────────────────────────────────
    /// @notice multiplier (bp) for `picks` numbers of which `hits` were drawn, at `risk`
    function multBP(uint256 risk, uint256 picks, uint256 hits) public pure returns (uint256 m) {
        if (risk >= RISKS || picks == 0 || picks > MAX_PICKS || hits > picks) revert BadInput();
        uint256 idx = risk * 65 + ((picks - 1) * (picks + 2)) / 2 + hits;
        bytes memory t = PAYS;
        assembly ("memory-safe") { m := shr(224, mload(add(add(t, 32), mul(idx, 4)))) }
    }
    function maxMultBP(uint256 risk, uint256 picks) public pure returns (uint256) { return multBP(risk, picks, picks); }

    // ── RNG ──────────────────────────────────────────────────
    struct Rng { bytes32 seed; uint256 i; uint256 word; }
    function _mod(Rng memory r, uint256 n) private pure returns (uint256) {
        uint256 i = r.i;
        uint256 k = i & 3;
        uint256 w;
        if (k == 0) {
            bytes32 s = r.seed;
            assembly ("memory-safe") {
                mstore(0x00, s)
                mstore(0x20, shl(224, shr(2, i)))
                w := keccak256(0x00, 0x24)
            }
            r.word = w;
        } else {
            w = r.word;
        }
        unchecked { r.i = i + 1; }
        return ((w >> (64 * k)) & 0xFFFFFFFFFFFFFFFF) % n;
    }
    /// @dev mask of the ten drawn numbers (bit n − 1 = number n)
    function _draw(bytes32 seed) internal pure returns (uint256 mask) {
        Rng memory r = Rng(seed, 0, 0);
        for (uint256 j = 0; j < DRAWN; ++j) {
            uint256 x = _mod(r, NUMBERS - j);
            for (uint256 b = 0; b < NUMBERS; ++b) {
                if ((mask >> b) & 1 == 1) continue;
                if (x == 0) { mask |= uint256(1) << b; break; }
                x--;
            }
        }
    }
    function _popcount(uint256 m) private pure returns (uint256 c) { while (m != 0) { c += m & 1; m >>= 1; } }

    // ── play ─────────────────────────────────────────────────
    /// @notice Pick 1–10 numbers (bitmask over 1…40) at a risk and buy the ticket.
    function play(uint256 amount, uint8 risk, uint256 picks) external nonReentrant whenNotPaused returns (uint256 id) {
        uint256 n = _popcount(picks);
        if (risk >= RISKS || picks == 0 || picks >> NUMBERS != 0 || n > MAX_PICKS || amount == 0 || amount >= MAX_AMOUNT) revert BadInput();
        uint256 nowB = _beginBet();
        uint16 rtp = config.rtpBP;
        uint256 maxPayout = (amount * maxMultBP(risk, n) * rtp) / (BP * BP);
        _openBet(amount, maxPayout);
        _pullAndFee(amount);
        id = totalTickets++;
        Ticket storage t = _tickets[id];
        t.player = msg.sender; t.commitBlock = uint48(nowB); t.rtpBP = rtp; t.risk = risk; t.picks = uint64(picks);
        t.amount = uint128(amount); t.maxPayout = uint128(maxPayout);
        _recordBet(msg.sender, id);
        emit TicketCommitted(id, msg.sender, amount, risk, picks);
    }

    /// @notice Permissionless: anyone may settle; the payout always goes to the ticket's player.
    function reveal(uint256 id) external nonReentrant returns (uint256 payout) {
        Ticket storage t = _tickets[id];
        if (t.player == address(0)) revert NotFound();
        if (t.settled) revert AlreadySettled();
        bytes32 seed = _seed(t.commitBlock, t.player, id);
        uint256 drawn = _draw(seed);
        uint256 h = _popcount(drawn & t.picks);
        payout = (uint256(t.amount) * multBP(t.risk, _popcount(t.picks), h) * t.rtpBP) / (BP * BP);
        if (payout > t.maxPayout) payout = t.maxPayout;   // unreachable by construction
        t.settled = true; t.drawn = uint64(drawn); t.hits = uint8(h); t.payout = uint128(payout);
        _closeBet(t.player, t.maxPayout, payout);
        emit TicketSettled(id, t.player, seed, t.picks, drawn, uint8(h), payout);
    }

    function forfeit(uint256 id) external nonReentrant {
        Ticket storage t = _tickets[id];
        if (t.player == address(0)) revert NotFound();
        if (t.settled) revert AlreadySettled();
        if (!_expireBet(id, _l2())) revert TooEarly();
    }

    function _expireBet(uint256 id, uint256 nowB) internal override returns (bool) {
        Ticket storage t = _tickets[id];
        if (t.settled) return true;
        if (!_isExpired(t.commitBlock, nowB)) return false;
        t.settled = true;
        _closeBet(t.player, t.maxPayout, 0);
        _countExpired();
        emit TicketForfeited(id, t.player);
        return true;
    }

    // ── views ────────────────────────────────────────────────
    /// @notice Replay any seed: the drawn-number mask.
    function previewDraw(bytes32 seed) external pure returns (uint256 drawn) { return _draw(seed); }

    function tickets(uint256 id) external view returns (
        address player, bool settled, uint256 amount, uint256 maxPayout, uint256 payout, uint256 rtpBP, uint256 commitBlock, uint8 risk, uint256 picks, uint256 drawn, uint8 hits
    ) {
        Ticket storage t = _tickets[id];
        return (t.player, t.settled, t.amount, t.maxPayout, t.payout, t.rtpBP, t.commitBlock, t.risk, t.picks, t.drawn, t.hits);
    }
    function userTickets(address u, uint256 i) external view returns (uint256) { return _userBetAt(u, i); }
    function getUserTicketCount(address u) external view returns (uint256) { return _userBetCount(u); }
}
